package com.smartattendance.service;
import com.smartattendance.dto.*;import com.smartattendance.exception.ResourceNotFoundException;import com.smartattendance.model.Subject;import com.smartattendance.repository.SubjectRepository;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;
@Service
public class SubjectService{private final SubjectRepository repo;private final CourseService courses;public SubjectService(SubjectRepository repo,CourseService courses){this.repo=repo;this.courses=courses;}public Page<SubjectResponse> search(String q,Pageable p){return(q==null||q.isBlank()?repo.findAll(p):repo.findByNameContainingIgnoreCaseOrCodeContainingIgnoreCase(q,q,p)).map(this::toResponse);}public SubjectResponse get(Long id){return toResponse(find(id));}public SubjectResponse create(SubjectRequest r){Subject s=new Subject();apply(s,r);return toResponse(repo.save(s));}public SubjectResponse update(Long id,SubjectRequest r){Subject s=find(id);apply(s,r);return toResponse(repo.save(s));}public void delete(Long id){repo.delete(find(id));}public Subject find(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Subject",id));}private void apply(Subject s,SubjectRequest r){s.setCode(r.code());s.setName(r.name());s.setCredits(r.credits());s.setCourse(courses.find(r.courseId()));}public SubjectResponse toResponse(Subject s){return new SubjectResponse(s.getId(),s.getCode(),s.getName(),s.getCredits(),s.getCourse().getId(),s.getCourse().getTitle());}}
